1	"use client";
2	
3	/**
4	 * FLAGSHIP — "Combined" greatest-hits game-server landing template.
5	 *
6	 * Curated merge of the three approved preview directions, composed into one
7	 * coherent premium page (NOT a stack of all three):
8	 *
9	 *   • from CINEMATIC — the full-bleed key-art hero with a navy-scrimmed
10	 *     asymmetric split + a genuinely-animated LIVE server panel (ticking player
11	 *     count, a drawn TPS graph, a streaming console) and slow scroll parallax;
12	 *     plus the plan cards and the blurred-art cinematic CTA.
13	 *   • from EDITORIAL — the numbered buying-reasons rail with the scroll-linked
14	 *     progress spine, beside a STICKY recommended plan card whose 47-second
15	 *     deploy ring counts up as it pins.
16	 *   • from COMMAND DECK — a HUD/console deploy beat: a glass terminal that types
17	 *     its boot sequence to "✓ online in 47s" next to animated telemetry gauges.
18	 *
19	 * Reuses the shared kit hooks/atoms + the scoped `pv-*` motion system so it
20	 * stays in the same design language. Everything respects prefers-reduced-motion.
21	 *
22	 * Net-new, PREVIEW-ONLY. Touches no live page or shared component.
23	 */
24	
25	import Link from "next/link";
26	import { useState } from "react";
27	import type { PreviewGame } from "./data";
28	import {
29	  usePrefersReducedMotion,
30	  useInViewOnce,
31	  useJitter,
32	  useCountUp,
33	  useParallax,
34	  useScrollProgress,
35	  useTypedLines,
36	  ReasonIcon,
37	} from "./kit";
38	import { GameLogo } from "@/components/marketing/GameLogo";
39	import {
40	  IconBolt,
41	  IconShield,
42	  IconNvme,
43	  IconGlobe,
44	  IconUsers,
45	  IconClock,
46	  IconCheck,
47	  IconServer,
48	  IconGauge,
49	} from "@/components/marketing/icons";
50	import { recommendedSpecForPlayers, playerSliderMax } from "@/lib/game-player-recommend";
51	
52	/* ── Live TPS sparkline — draws on view, pulsing playhead (from Cinematic) ── */
53	function TpsGraph({ accent, active, reduced }: { accent: string; active: boolean; reduced: boolean }) {
54	  const pts = [19.9, 20, 19.8, 20, 20, 19.7, 20, 19.9, 20, 20, 19.8, 20];
55	  const w = 220;
56	  const h = 46;
57	  const min = 19.5;
58	  const max = 20.2;
59	  const step = w / (pts.length - 1);
60	  const coords = pts.map((v, i) => {
61	    const x = i * step;
62	    const y = h - ((v - min) / (max - min)) * h;
63	    return [x, y] as const;
64	  });
65	  const line = coords.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
66	  const area = `${line} L${w} ${h} L0 ${h} Z`;
67	  const [ex, ey] = coords[coords.length - 1];
68	  return (
69	    <svg viewBox={`0 0 ${w} ${h}`} className="h-[46px] w-full" preserveAspectRatio="none" aria-hidden>
70	      <defs>
71	        <linearGradient id="pv-cmb-tps-fill" x1="0" y1="0" x2="0" y2="1">
72	          <stop offset="0%" stopColor={accent} stopOpacity="0.35" />
73	          <stop offset="100%" stopColor={accent} stopOpacity="0" />
74	        </linearGradient>
75	      </defs>
76	      <path d={area} fill="url(#pv-cmb-tps-fill)" />
77	      <path
78	        d={line}
79	        fill="none"
80	        stroke={accent}
81	        strokeWidth="1.6"
82	        strokeLinecap="round"
83	        strokeLinejoin="round"
84	        className={reduced || !active ? "" : "pv-draw"}
85	      />
86	      <circle cx={ex} cy={ey} r="3" fill={accent} className={reduced ? "" : "motion-safe:animate-pulse-dot"} />
87	    </svg>
88	  );
89	}
90	
91	/* ── Floating LIVE control panel — hero right column (from Cinematic) ──────── */
92	function LiveOpsPanel({ game }: { game: PreviewGame }) {
93	  const reduced = usePrefersReducedMotion();
94	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
95	  const totalSlots = 60;
96	  const players = useJitter(47, 3, seen, 2400, reduced);
97	  const filled = Math.min(totalSlots, players);
98	  const cpu = useCountUp(38, seen, 1200, reduced);
99	  const ping = useJitter(12, 2, seen, 3000, reduced);
100	
101	  const logLines = [
102	    { t: "player connected · s.singe", c: "text-emerald-300" },
103	    { t: "player connected · DevReez", c: "text-emerald-300" },
104	    { t: "[Oxide] loaded 14 plugins", c: "text-slate-400" },
105	    { t: "map saved (0.4s) · autobackup ok", c: "text-slate-500" },
106	  ];
107	
108	  return (
109	    <div ref={ref} className={reduced ? "" : "pv-float"}>
110	      <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-[#080d18]/85 shadow-2xl shadow-black/50 backdrop-blur-xl">
111	        <div
112	          className="pointer-events-none absolute -inset-16 -z-10 opacity-70"
113	          style={{ background: `radial-gradient(45% 45% at 80% 0%, ${game.accent}33, transparent 70%)` }}
114	          aria-hidden
115	        />
116	        {/* header */}
117	        <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2.5">
118	          <GameLogo family={game.family} size={22} />
119	          <span className="ml-0.5 truncate text-[11px] font-medium text-slate-300">{game.worldName}</span>
120	          <span className="ml-auto inline-flex shrink-0 items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-emerald-300">
121	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
122	            running
123	          </span>
124	        </div>
125	
126	        <div className="space-y-4 p-4">
127	          {/* live stat row */}
128	          <div className="grid grid-cols-3 gap-2.5">
129	            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
130	              <p className="text-[10px] uppercase tracking-wide text-slate-500">Players</p>
131	              <p className="mt-0.5 font-mono text-lg font-semibold text-white tabular-nums">
132	                {filled}
133	                <span className="text-sm text-slate-500">/{totalSlots}</span>
134	              </p>
135	            </div>
136	            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
137	              <p className="text-[10px] uppercase tracking-wide text-slate-500">Ping</p>
138	              <p className="mt-0.5 font-mono text-lg font-semibold text-white tabular-nums">
139	                {ping}
140	                <span className="text-sm text-slate-500"> ms</span>
141	              </p>
142	            </div>
143	            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
144	              <p className="text-[10px] uppercase tracking-wide text-slate-500">CPU</p>
145	              <p className="mt-0.5 font-mono text-lg font-semibold text-white tabular-nums">
146	                {cpu}
147	                <span className="text-sm text-slate-500">%</span>
148	              </p>
149	            </div>
150	          </div>
151	
152	          {/* TPS graph */}
153	          <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3.5 pb-2 pt-3">
154	            <div className="flex items-center justify-between">
155	              <p className="text-[11px] font-medium text-slate-400">Server TPS · last 60s</p>
156	              <p className="font-mono text-[11px] font-semibold" style={{ color: game.accent }}>
157	                20.0
158	              </p>
159	            </div>
160	            <div className="mt-1">
161	              <TpsGraph accent={game.accent} active={seen} reduced={reduced} />
162	            </div>
163	          </div>
164	
165	          {/* player slots */}
166	          <div>
167	            <div className="mb-2 flex items-center justify-between text-[11px]">
168	              <span className="text-slate-400">Player slots</span>
169	              <span className="font-mono text-slate-500">{filled} online</span>
170	            </div>
171	            <div className="grid grid-cols-12 gap-1">
172	              {Array.from({ length: totalSlots }).map((_, i) => (
173	                <span
174	                  key={i}
175	                  className={`h-2.5 origin-bottom rounded-[3px] ${reduced ? "" : "motion-safe:animate-grow-up"} ${
176	                    i < filled ? "" : "border border-white/10 bg-white/[0.03]"
177	                  }`}
178	                  style={
179	                    i < filled
180	                      ? { background: `linear-gradient(to top, ${game.accent}, #3b82f6)`, animationDelay: `${i * 14}ms` }
181	                      : undefined
182	                  }
183	                />
184	              ))}
185	            </div>
186	          </div>
187	
188	          {/* streaming console */}
189	          <div className="rounded-xl border border-white/[0.06] bg-black/40 p-3 font-mono text-[11px] leading-relaxed">
190	            {logLines.map((l, i) => (
191	              <div
192	                key={i}
193	                className={`${l.c} ${reduced ? "" : "motion-safe:animate-line-in"}`}
194	                style={{ animationDelay: `${300 + i * 260}ms` }}
195	              >
196	                {l.t}
197	              </div>
198	            ))}
199	            <div className="mt-0.5 flex items-center text-slate-500">
200	              <span className="text-emerald-400">&gt;&nbsp;</span>
201	              <span className="inline-block h-3 w-1.5 bg-slate-400 motion-safe:animate-blink" />
202	            </div>
203	          </div>
204	        </div>
205	      </div>
206	    </div>
207	  );
208	}
209	
210	/* ── 47-second deploy ring — counts up + fills on view (from Editorial) ───── */
211	function DeployRing({ accent }: { accent: string }) {
212	  const reduced = usePrefersReducedMotion();
213	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
214	  const val = useCountUp(47, seen, 1300, reduced);
215	  const r = 34;
216	  const c = 2 * Math.PI * r;
217	  const offset = c * (1 - Math.min(1, val / 47));
218	  return (
219	    <div ref={ref} className="flex items-center gap-4">
220	      <div className="relative h-[92px] w-[92px] shrink-0">
221	        <svg viewBox="0 0 92 92" className="h-full w-full -rotate-90">
222	          <circle cx="46" cy="46" r={r} fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="6" />
223	          <circle
224	            cx="46"
225	            cy="46"
226	            r={r}
227	            fill="none"
228	            stroke={accent}
229	            strokeWidth="6"
230	            strokeLinecap="round"
231	            strokeDasharray={c}
232	            strokeDashoffset={offset}
233	          />
234	        </svg>
235	        <div className="absolute inset-0 flex flex-col items-center justify-center">
236	          <span className="font-mono text-2xl font-bold tabular-nums text-white">{val}</span>
237	          <span className="text-[10px] font-medium uppercase tracking-wide text-slate-500">sec</span>
238	        </div>
239	      </div>
240	      <div>
241	        <p className="text-sm font-semibold text-white">Live in 47 seconds</p>
242	        <p className="mt-1 text-xs leading-relaxed text-slate-400">
243	          From checkout to a running, connect-ready server — measured, not marketing.
244	        </p>
245	      </div>
246	    </div>
247	  );
248	}
