250	/* ── animated telemetry gauge (from Command Deck) ─────────────────────────── */
251	function Gauge({
252	  label,
253	  value,
254	  suffix,
255	  pct,
256	  accent,
257	  active,
258	  reduced,
259	  delay,
260	}: {
261	  label: string;
262	  value: number | string;
263	  suffix?: string;
264	  pct: number;
265	  accent: string;
266	  active: boolean;
267	  reduced: boolean;
268	  delay: number;
269	}) {
270	  return (
271	    <div>
272	      <div className="mb-1.5 flex items-baseline justify-between">
273	        <span className="text-[11px] font-medium uppercase tracking-wide text-slate-400">{label}</span>
274	        <span className="font-mono text-sm font-semibold tabular-nums text-white">
275	          {value}
276	          {suffix && <span className="text-slate-500">{suffix}</span>}
277	        </span>
278	      </div>
279	      <div className="h-2 w-full overflow-hidden rounded-full bg-white/[0.06]">
280	        <div
281	          className={`h-full origin-left rounded-full ${reduced || !active ? "" : "motion-safe:animate-grow-x"}`}
282	          style={{
283	            width: `${pct}%`,
284	            background: `linear-gradient(90deg, #3b82f6, ${accent})`,
285	            animationDelay: `${delay}ms`,
286	          }}
287	        />
288	      </div>
289	    </div>
290	  );
291	}
