293	/* ── HUD deploy beat — typing terminal + telemetry gauges (from Command Deck) */
294	function DeployBeat({ game }: { game: PreviewGame }) {
295	  const reduced = usePrefersReducedMotion();
296	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
297	  const players = useJitter(47, 3, seen, 2500, reduced);
298	  const cpu = useJitter(38, 4, seen, 2200, reduced);
299	  const ram = useJitter(61, 3, seen, 2800, reduced);
300	  const { done, current, caret } = useTypedLines(game.boot, seen, reduced);
301	  const totalSlots = 60;
302	
303	  return (
304	    <div ref={ref} className={reduced ? "" : "pv-float-slow"}>
305	      <div
306	        className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#070c17]/90 backdrop-blur-xl"
307	        style={{ boxShadow: `0 40px 120px -50px ${game.accent}80, 0 0 0 1px rgba(255,255,255,0.04)` }}
308	      >
309	        {/* drifting grid backdrop */}
310	        <div
311	          className={`pointer-events-none absolute inset-0 opacity-[0.5] ${reduced ? "" : "pv-grid-pan"}`}
312	          style={{
313	            backgroundImage:
314	              "linear-gradient(rgba(255,255,255,0.035) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.035) 1px, transparent 1px)",
315	            backgroundSize: "40px 40px",
316	          }}
317	          aria-hidden
318	        />
319	        <div
320	          className="pointer-events-none absolute -inset-24 opacity-70"
321	          style={{ background: `radial-gradient(40% 40% at 85% 0%, ${game.accent}30, transparent 70%)` }}
322	          aria-hidden
323	        />
324	
325	        {/* deck header */}
326	        <div className="relative flex items-center gap-3 border-b border-white/[0.07] bg-white/[0.02] px-5 py-3">
327	          <GameLogo family={game.family} size={26} />
328	          <span className="text-sm font-semibold text-white">{game.worldName}</span>
329	          <span className="hidden font-mono text-[11px] text-slate-500 sm:inline">{game.region}</span>
330	          <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide text-emerald-300">
331	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
332	            live
333	          </span>
334	        </div>
335	
336	        <div className="relative grid gap-4 p-4 lg:grid-cols-5 lg:p-5">
337	          {/* deploy terminal — HUD framed, types boot sequence */}
338	          <div className="lg:col-span-3">
339	            <div className="relative h-full overflow-hidden rounded-2xl border border-white/10 bg-black/55 p-4 pt-5 font-mono text-[12px] leading-relaxed">
340	              {/* scan line */}
341	              {!reduced && (
342	                <div
343	                  className="pv-scan pointer-events-none absolute inset-x-0 top-0 h-16"
344	                  style={{ background: `linear-gradient(to bottom, ${game.accent}00, ${game.accent}1f, ${game.accent}00)` }}
345	                  aria-hidden
346	                />
347	              )}
348	              {/* corner brackets */}
349	              {["left-2.5 top-2.5 border-l-2 border-t-2", "right-2.5 top-2.5 border-r-2 border-t-2", "left-2.5 bottom-2.5 border-l-2 border-b-2", "right-2.5 bottom-2.5 border-r-2 border-b-2"].map(
350	                (pos) => (
351	                  <span key={pos} className={`absolute h-5 w-5 rounded-[3px] ${pos}`} style={{ borderColor: `${game.accent}aa` }} aria-hidden />
352	                ),
