354	              <div className="mb-3 flex items-center gap-1.5">
355	                <span className="h-2.5 w-2.5 rounded-full bg-red-500/70" />
356	                <span className="h-2.5 w-2.5 rounded-full bg-amber-400/70" />
357	                <span className="h-2.5 w-2.5 rounded-full bg-emerald-400/70" />
358	                <span className="ml-2 text-[10px] uppercase tracking-wider text-slate-500">deploy · {game.name.toLowerCase()}</span>
359	              </div>
360	              <div className="relative">
361	                {done.map((l, i) => {
362	                  const ok = l.startsWith("✓");
363	                  return (
364	                    <div key={i} className={ok ? "font-semibold" : "text-slate-400"} style={ok ? { color: game.accent } : undefined}>
365	                      {l}
366	                    </div>
367	                  );
368	                })}
369	                {caret < game.boot.length && (
370	                  <div className="text-slate-300">
371	                    {current}
372	                    <span className="ml-0.5 inline-block h-3.5 w-1.5 translate-y-[2px] bg-slate-300 motion-safe:animate-blink" />
373	                  </div>
374	                )}
375	              </div>
376	            </div>
377	          </div>
378	
379	          {/* telemetry gauges rail */}
380	          <div className="flex flex-col gap-4 lg:col-span-2">
381	            <div className="relative rounded-2xl border border-white/[0.07] bg-white/[0.02] p-4">
382	              <p className="mb-4 text-[11px] font-semibold uppercase tracking-wider text-slate-500">Live telemetry</p>
383	              <div className="space-y-4">
384	                <Gauge label="Players" value={players} suffix={`/${totalSlots}`} pct={(players / totalSlots) * 100} accent={game.accent} active={seen} reduced={reduced} delay={80} />
385	                <Gauge label="CPU" value={cpu} suffix="%" pct={cpu} accent={game.accent} active={seen} reduced={reduced} delay={160} />
386	                <Gauge label="Memory" value={ram} suffix="%" pct={ram} accent={game.accent} active={seen} reduced={reduced} delay={240} />
387	                <Gauge label="TPS" value="20.0" pct={100} accent={game.accent} active={seen} reduced={reduced} delay={320} />
388	              </div>
389	            </div>
390	            <div className="flex items-center justify-between rounded-2xl border border-white/[0.07] bg-white/[0.02] px-4 py-3 text-[11px] text-slate-400">
391	              <span className="font-mono">uptime 4d 06h</span>
392	              <span className="inline-flex items-center gap-1.5 text-emerald-300">
393	                <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" /> healthy
394	              </span>
395	            </div>
396	          </div>
397	        </div>
398	      </div>
399	    </div>
