403	/* ── numbered reason row on the scroll spine (from Editorial) ─────────────── */
404	function ReasonRow({ game, r, delay }: { game: PreviewGame; r: PreviewGame["reasons"][number]; delay: number }) {
405	  const { ref, seen } = useInViewOnce<HTMLLIElement>();
406	  return (
407	    <li
408	      ref={ref}
409	      className={`relative transition-all duration-700 ease-out ${seen ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"}`}
410	      style={{ transitionDelay: `${delay}ms` }}
411	    >
412	      <span
413	        className="absolute -left-[26px] top-1.5 h-3 w-3 rounded-full ring-4 ring-navy-950"
414	        style={{ background: game.accent }}
415	        aria-hidden
416	      />
417	      <div className="flex items-baseline gap-4">
418	        <span className="font-mono text-3xl font-bold tabular-nums" style={{ color: game.accent }}>
419	          {r.n}
420	        </span>
421	        <div>
422	          <h3 className="flex items-center gap-2.5 text-xl font-semibold text-white">
423	            <span style={{ color: game.accent }} className="opacity-90">
424	              <ReasonIcon icon={r.icon} size={18} />
425	            </span>
426	            {r.title}
427	          </h3>
428	          <p className="mt-2 max-w-lg text-[15px] leading-relaxed text-slate-400">{r.body}</p>
429	        </div>
430	      </div>
431	    </li>
432	  );
433	}
434	
435	/* ── Interactive pricing configurator ─────────────────────────────────────────
436	 * Drag the player count and the recommended plan + price update live. The
437	 * recommended RAM/vCPU/NVMe readout is GROUNDED in the real fitted player→resource
438	 * curve (lib/game-player-recommend — the same math the live GameDeployWizard uses),
439	 * and the plan match is driven by each plan's advertised slot capacity (falling
440	 * back to the RAM curve for VPS-style, slot-less plans). We reuse that recommend
441	 * logic rather than the DB-shaped <GameConfigurator/> because this preview runs on
442	 * PreviewGame data, not db.gamePlan rows — but the interaction language (player
443	 * control + brand-accented tiers) matches the site's GameConfigurator. */
444	function ramGbOf(ram: string) {
445	  return parseFloat(ram) || 0;
446	}
447	function gbLabel(mb: number) {
448	  const v = mb / 1024;
449	  return `${v.toFixed(v % 1 ? 1 : 0)} GB`;
450	}
451	
452	function PlanConfigurator({ game }: { game: PreviewGame }) {
453	  const reduced = usePrefersReducedMotion();
454	  const plans = game.plans;
455	
456	  const slotVals = plans.map((p) => p.slots).filter((s): s is number => s != null);
457	  const anySlots = slotVals.length > 0;
458	  const topSlots = anySlots ? Math.max(...slotVals) : null;
459	
460	  // Slider spans the plan ladder with ~30% headroom (to show "past our tiers"),
461	  // capped by the recommend module's own per-family ceiling.
462	  const sliderMax = topSlots
463	    ? Math.min(playerSliderMax(game.family), Math.max(topSlots + 16, Math.round(topSlots * 1.3)))
464	    : 64;
465	
466	  const popular = plans.find((p) => p.popular);
467	  const [players, setPlayers] = useState(popular?.slots ?? topSlots ?? Math.round(sliderMax / 2));
468	
469	  const spec = recommendedSpecForPlayers(game.family, players);
470	  const recRamGB = spec.ramMB / 1024;
471	
472	  const matchIdx = (() => {
473	    if (anySlots) {
474	      const i = plans.findIndex((p) => p.slots != null && p.slots >= players);
475	      return i === -1 ? plans.length - 1 : i;
476	    }
477	    const i = plans.findIndex((p) => ramGbOf(p.ram) >= recRamGB);
478	    return i === -1 ? plans.length - 1 : i;
479	  })();
480	  const matched = plans[matchIdx];
481	  const beyondTop = topSlots != null && players > topSlots;
482	
